// Wi-Fi ile LED kontrolü: ESP32 web sunucusu açar, sayfadaki düğmeler LED'i yönetir.
#include <WiFi.h>
#include <WebServer.h>

const char* AG_ADI = "EvimWiFi";     // kendi Wi-Fi ağının adı
const char* PAROLA = "parola123";    // kendi Wi-Fi parolan
const int LED_PIN = 4;

WebServer sunucu(80);
bool ledAcik = false;

String sayfa() {
  String s = "<!doctype html><html><head><meta charset='utf-8'>";
  s += "<meta name='viewport' content='width=device-width,initial-scale=1'><title>ESP32 LED</title>";
  s += "<style>body{font-family:sans-serif;text-align:center;padding:24px}";
  s += "a{display:inline-block;margin:8px;padding:14px 28px;border-radius:10px;color:#fff;text-decoration:none;font-size:20px}</style>";
  s += "</head><body><h1>ESP32 LED kontrolü</h1><p>LED şu an: <b>";
  s += ledAcik ? "AÇIK" : "KAPALI";
  s += "</b></p><a href='/ac' style='background:#16a34a'>Aç</a><a href='/kapat' style='background:#dc2626'>Kapat</a>";
  s += "<p>Çalışma süresi: " + String(millis() / 1000) + " sn</p></body></html>";
  return s;
}

void anaSayfa() {
  sunucu.send(200, "text/html", sayfa());
}

void ledAc() {
  ledAcik = true;
  digitalWrite(LED_PIN, HIGH);
  sunucu.sendHeader("Location", "/");
  sunucu.send(303);
}

void ledKapat() {
  ledAcik = false;
  digitalWrite(LED_PIN, LOW);
  sunucu.sendHeader("Location", "/");
  sunucu.send(303);
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  WiFi.mode(WIFI_STA);
  WiFi.begin(AG_ADI, PAROLA);
  Serial.print("Wi-Fi'ye baglaniyor");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("Baglandi. Tarayicida ac: http://");
  Serial.println(WiFi.localIP());

  sunucu.on("/", anaSayfa);
  sunucu.on("/ac", ledAc);
  sunucu.on("/kapat", ledKapat);
  sunucu.begin();
}

void loop() {
  sunucu.handleClient();
}
